__NUXT_JSONP__("/inclusion/publicaciones/sembrando_el_cambio-_hacia_un_futuro_con_trabajo_justo_para_las_trabajadoras_agricolas_en_mexico", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"sembrando_el_cambio-_hacia_un_futuro_con_trabajo_justo_para_las_trabajadoras_agricolas_en_mexico",title:"Sembrando el cambio. Hacia un futuro con trabajo justo para las trabajadoras agrícolas en México",date:"2025-09-26T19:36:48.183Z",img:"https:\u002F\u002Fucarecdn.com\u002F20a9d43c-6811-4ea1-bc91-ecce211366da\u002F","img-alt":"Sembrando el cambio",autor:"Ethos, Fundación Avina, Oxfam México, ProDESC",category:d,extracto:"Este documento analiza algunas de las principales barreras estructurales que enfrentan las trabajadoras agrícolas en México para acceder a un trabajo justo, con el objetivo de visibilizar su situación y generar recomendaciones de políticas públicas que contribuyan a garantizar sus derechos laborales y mejorar su calidad de vida.",file:"https:\u002F\u002Fucarecdn.com\u002F3a367950-03ba-49ff-b2df-8944a4aea4fb\u002F",toc:[],body:{type:e,children:[{type:b,tag:c,props:{},children:[{type:a,value:"El sector agrícola en México desempeña un papel fundamental en la economía nacional y la seguridad alimentaria. Dentro de este sector, las mujeres trabajadoras agrícolas realizan una contribución invaluable, a pesar de enfrentar condiciones laborales sumamente precarias. Su labor, a menudo subvalorada e invisibilizada, es esencial para la producción de alimentos que llegan a nuestras mesas. No obstante, estas mujeres se enfrentan a una realidad laboral marcada por la informalidad, carencia de seguridad social, violencias y falta de mecanismos para denunciar y hacer justicia por estas violaciones a sus derechos."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fsembrando_el_cambio-_hacia_un_futuro_con_trabajo_justo_para_las_trabajadoras_agricolas_en_mexico",extension:g,createdAt:h,updatedAt:h},publicaciones:[{slug:"conectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",title:"Conectadas al cambio: por un trabajo justo para las mujeres en plataformas digitales",date:"2026-01-29T21:30:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fb777d5d7-cd1f-4afd-b80b-6eb9e1011bc3\u002F","img-alt":"Por un trabajo justo para las mujeres en plataformas digitales",autor:"Ethos, Fundación Avina, ProDESC y Oxfam México",category:d,extracto:"El objetivo de este documento es analizar y evidenciar las barreras sistémicas que excluyen a las mujeres de este sector, con base en la experiencia directa de las trabajadoras. A través de la sistematización de entrevistas y talleres con colectivas de conductoras y repartidoras, se contrastan las propuestas de la reforma en materia de trabajo en plataformas digitales con la realidad cotidiana. El análisis muestra cómo la violencia de género, la opacidad de los algoritmos y la falta de una red de cuidados convierten la supuesta “flexibilidad laboral” en una fuente de precariedad para ellas. A partir de este diagnóstico, se presentan recomendaciones de política pública y buenas prácticas empresariales dirigidas a cerrar la brecha entre la ley y la realidad, para que la promesa del trabajo justo en la era digital sea, verdaderamente, para todas y todos. ",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F651cff88-f77e-4a4c-a59c-f8b0d6873e38\u002F",toc:[],body:{type:e,children:[{type:b,tag:c,props:{},children:[{type:a,value:"El objetivo de este documento es analizar y evidenciar las barreras sistémicas que excluyen a las mujeres de este sector, con base en la experiencia directa de las trabajadoras. A través de la sistematización de entrevistas y talleres con colectivas de conductoras y repartidoras, se contrastan las propuestas de la reforma en materia de trabajo en plataformas digitales con la realidad cotidiana. El análisis muestra cómo la violencia de género, la opacidad de los algoritmos y la falta de una red de cuidados convierten la supuesta “flexibilidad laboral” en una fuente de precariedad para ellas. A partir de este diagnóstico, se presentan recomendaciones de política pública y buenas prácticas empresariales dirigidas a cerrar la brecha entre la ley y la realidad, para que la promesa del trabajo justo en la era digital sea, verdaderamente, para todas y todos."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fconectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",extension:g,createdAt:"2026-07-19T00:56:17.268Z",updatedAt:"2026-07-19T00:56:17.269Z"},{slug:"cuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",title:"Cuando el desastre golpea distinto: mujeres y hombres tras el huracán Otis",date:"2026-05-04T06:00:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F7aea98e9-3923-4f9f-8d26-f18231e79b35\u002F",autor:"Ethos, Centro Nacional de Prevención de Desastres ",category:d,extracto:"El huracán Otis evidenció cómo las desigualdades influyen en la preparación, los impactos y la recuperación tras un desastre.  Este informe analiza, desde una perspectiva de género e interseccionalidad, cómo mujeres, población indígena y afromexicana enfrentaron de forma diferenciada los efectos del huracán en Acapulco, y propone recomendaciones para construir respuestas más justas y efectivas.",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F12bb5aff-9368-40ac-b7c6-1d2866421317\u002F",toc:[],body:{type:e,children:[{type:b,tag:c,props:{},children:[{type:a,value:"El huracán Otis no solo dejó daños materiales sin precedentes en Acapulco: también evidenció y profundizó desigualdades estructurales que influyeron en la preparación, la experiencia durante la emergencia y las posibilidades de recuperación de la población."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Este informe presenta los hallazgos de una encuesta aplicada en Acapulco para analizar los impactos diferenciados del desastre entre mujeres y hombres, así como entre distintos grupos sociales. La evidencia muestra que factores como el género, el trabajo de cuidados y las condiciones de marginación influyen directamente en quién puede prepararse, quién enfrenta mayores riesgos y quién logra recuperarse."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"El documento ofrece recomendaciones para construir políticas de prevención, respuesta y recuperación más justas, resilientes y con perspectiva de género."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fcuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",extension:g,createdAt:j,updatedAt:j},{slug:"cuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",title:"Cuidados para la primera infancia: Recomendaciones hacia la conformación del Sistema Nacional de Cuidados",date:"2025-03-18T14:41:00.000Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffca2a0ef-b4dd-4e5f-9a7f-c17d24f27d70\u002F-\u002Fcrop\u002F1047x1377\u002F18,15\u002F-\u002Fpreview\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos, Early Institute y el Centro de Investigación Económica y Presupuestaria ",category:d,extracto:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez. ",file:"https:\u002F\u002Fucarecdn.com\u002Fb2c423fb-64a1-42e7-9f85-07fff85a84e8\u002F",toc:[],body:{type:e,children:[{type:b,tag:c,props:{},children:[{type:a,value:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fcuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",extension:g,createdAt:k,updatedAt:k}]}],fetch:{},mutations:[]}}("text","element","p","inclusion","root","\u002Fpublicaciones",".md","2025-11-25T01:24:03.300Z","\n","2026-07-19T00:56:17.270Z","2025-04-23T06:21:15.398Z")));